# ---- Helper functions ----

def log_message(message, tag=None): # UI printing
    scrolled_text_output.configure(state='normal')
    scrolled_text_output.tag_configure("issue_none", foreground="violet")
    scrolled_text_output.tag_configure("issue_incorrect", foreground="red")
    if tag==None:
        scrolled_text_output.insert(tk.END, message + "\n", tag)
        scrolled_text_output.see(tk.END)
    elif tag=='incorrect':
        scrolled_text_output.insert(tk.END, message + "\n", "issue_incorrect")
        scrolled_text_output.see(tk.END)
    elif tag=='none':
        scrolled_text_output.insert(tk.END, message + "\n", "issue_none")
        scrolled_text_output.see(tk.END)
    
    scrolled_text_output.configure(state='disabled')

def wait_for_clickable(driver, by, identifier, timeout=30): # Waits for elements to be clickable
    return WebDriverWait(driver, timeout).until(EC.element_to_be_clickable((by, identifier)))

def wait_for_presence(driver, by, identifier, timeout=30): # Waits for elements to be present
    return WebDriverWait(driver, timeout).until(EC.presence_of_element_located((by, identifier)))

# ---- Login function ----

def perform_login(driver, user, pw):
    wait = WebDriverWait(driver, 10)
    driver.get(url)
    try:
        wait_for_clickable(driver, By.ID, 'external-login').click()
        log_message("External login button clicked")

        time.sleep(time_access_learnosity)

        try:
            wait_for_clickable(driver, By.ID, 'otherTileText').click()
        except NoSuchElementException:
            pass

        # Enter username and click login button
        time.sleep(time_access_learnosity)

        input_username = wait_for_presence(driver, By.NAME, 'loginfmt')
        log_message("Logging in Learnosity...")
        input_username.send_keys(user)
        wait_for_clickable(driver, By.ID, 'idSIButton9').click()

        # Check if username errors

        try:
            driver.find_element(By.ID, 'usernameError')
            log_message('Incorrect username. Please close this app and check.\n', 'incorrect')
            return False
        except NoSuchElementException:
            pass

        # Enter password and continue logging in

        time.sleep(time_access_learnosity)

        input_password = wait_for_presence(driver, By.NAME, 'passwd')
        input_password.send_keys(pw)
        wait_for_clickable(driver, By.ID, 'idSIButton9').click()

        # Handle "Stay signed in" prompt
        try:
            wait_for_presence(driver, By.XPATH, '//div[@class="row text-title" and @role="heading" and @aria-level="1" and contains(@data-bind, "STR_Kmsi_Title")]')
            wait_for_clickable(driver, By.ID, 'idSIButton9').click()
        except Exception:
            pass

        return True
    except Exception as e:
        log_message(f"Login failed: {e}", "incorrect")
        return False

# ---- Tag extraction ----

def extract_tags(driver):
    tag_names = ["Assessment Type", "Domain", "Term", "Grade Level", "Unit Number", "Lesson Number"]
    tags = {}
    for name in tag_names:
        try:
            driver.find_element(By.XPATH, f'//h3[@data-authorapi-selector="lrn-author-settings-tag-type" and contains(text(), "{name}")]')
            tag_elem = driver.find_element(By.XPATH, f'//h3[@data-authorapi-selector="lrn-author-settings-tag-type" and contains(text(), "{name}")]/following-sibling::ul/li/span[@data-authorapi-selector="lrn-author-settings-tags-label"]')
            tags[name] = tag_elem.text.strip()
        except Exception:
            tags[name] = None
    return tags

