# ---- Validation ----

def validate_item(item_id, expected_tags, expected_properties, driver):
    item_url = f'{url}/Items/ItemAuthoring?ref={item_id}'

    driver.get(item_url)

    wait_for_clickable(driver, By.CSS_SELECTOR, 'button[data-authorapi-selector="settings"]').click()
    wait_for_clickable(driver, By.CSS_SELECTOR, 'button[data-tab-id="tags"]').click()

    actual_tags = extract_tags(driver)

        
    for tag, expected_value in expected_tags.items():
        if actual_tags.get(tag) is None:
            log_message(f"Item {item_id.strip()}: Missing tag '{tag}'", "none")
        elif actual_tags[tag] == expected_value:
            log_message(f"Item {item_id.strip()}: Correct {tag} ({expected_value})")
        else:
            log_message(f"Item {item_id.strip()}: Incorrect {tag}. Expected '{expected_value}' but got '{actual_tags[tag]}'", "incorrect")

    wait_for_clickable(driver, By.CSS_SELECTOR, 'button[data-authorapi-selector="item-settings-exit-button"]').click()
    wait_for_clickable(driver, By.CSS_SELECTOR, 'button[data-authorapi-selector="config-edit-btn"]').click()

    # wait_for_presence(driver, By.XPATH, '//ul[@class="lrn_mcqgroup lrn_mcqgroup-horizontal"]')

    time.sleep(time_access_learnosity)
    time.sleep(time_access_learnosity)


    item_properties = get_item_properties(driver)

    for prop, expected_val in expected_properties.items():

        actual_val = item_properties.get(prop)
        print(actual_val)
        print(expected_val)
        if actual_val == expected_val:
            log_message(f"Item {item_id.strip()}: Correct {prop} ({expected_val})")
        else:
            log_message(f"Item {item_id.strip()}: Incorrect {prop}. Expected '{expected_val}' but got '{actual_val}'", "incorrect")

# ---- Identify question type ----
def identify_item_property(item_id, driver):
    item_url = f'{url}/Items/ItemAuthoring?ref={item_id}'

    driver.get(item_url)

    wait_for_clickable(driver, By.CSS_SELECTOR, 'button[data-authorapi-selector="config-edit-btn"]').click()


    # wait_for_presence(driver, By.XPATH, '//ul[@class="lrn_mcqgroup lrn_mcqgroup-horizontal"]')

    time.sleep(time_access_learnosity)
    time.sleep(time_access_learnosity)

    if driver.find_elements(By.XPATH, '//div[@class="lrn-question-preview"]//li[@class="lrn-mcq-option"]'):
        actual_number_of_choices = driver.find_elements(By.XPATH, '//div[@class="lrn-question-preview"]//li[@class="lrn-mcq-option"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), len(actual_number_of_choices)]
    elif driver.find_elements(By.XPATH, '//span[@data-widget="lrn_response"]'):
        actual_number_of_response_boxes = driver.find_elements(By.XPATH, '//span[@data-widget="lrn_response"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), len(actual_number_of_response_boxes)]
    elif driver.find_elements(By.XPATH, '//span[@class="lrn-qe-response"]'):
        actual_number_of_response_boxes = driver.find_elements(By.XPATH, '//span[@class="lrn-qe-response"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), len(actual_number_of_response_boxes)]
    elif driver.find_elements(By.XPATH, '//div[@data-lrn-qe-input-path="validation.valid_response.value"]//span[@class="lrn-stem-text"]'):
        actual_number_of_choices = driver.find_elements(By.XPATH, '//div[@data-lrn-qe-input-path="validation.valid_response.value"]//span[@class="lrn-stem-text"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), len(actual_number_of_choices)]
    elif driver.find_elements(By.XPATH, '//div[@class="lrn_imagecloze_response moveable"]'):
        actual_number_of_choices = driver.find_elements(By.XPATH, '//div[@class="lrn_imagecloze_response moveable"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), len(actual_number_of_choices)]
    
    else:
        # actual_number_of_response_boxes = driver.find_elements(By.XPATH, '//span[@data-widget="lrn_response"]')
        question_type = driver.find_element(By.XPATH, '//h3[@class="lrn-qe-heading lrn-qe-inline-block"]')
        return [question_type.text.strip(), 5]


